import type { PeerConfig } from "./api/peerConfig";
import { SRTP_PROFILE } from "./const";
import { createWebRtcDomException, createWebRtcTypeError } from "./errors";
import { debug, Event } from "./imports/common";
import type { RTCRtpTransceiver, TransceiverManager } from "./media";
import type { RTCStats } from "./media/stats";
import type { SctpTransportManager } from "./sctpManager";
import type { BundlePolicy, MediaDescription, SessionDescription } from "./sdp";
import {
  type DtlsKeys,
  RTCCertificate,
  RTCDtlsTransport,
} from "./transport/dtls";
import type {
  IceGathererState,
  RTCIceCandidate,
  RTCIceCandidateInit,
  RTCIceConnectionState,
} from "./transport/ice";
import { IceCandidate, RTCIceGatherer, RTCIceTransport } from "./transport/ice";
import type { RTCSctpTransport } from "./transport/sctp";
import type { ConnectionState } from "./types/domain";
import { parseIceServers, resolveTurnTransport } from "./utils";

const log = debug(
  "werift:packages/webrtc/src/transport/secureTransportManager.ts",
);
export class SecureTransportManager {
  connectionState: ConnectionState = "new";
  iceConnectionState: RTCIceConnectionState = "new";
  iceGatheringState: IceGathererState = "new";
  certificate?: RTCCertificate;
  /**Generation of this peer connection's own certificate, shared by concurrent createOffer / createAnswer calls */
  private certificatePromise?: Promise<RTCCertificate>;

  readonly iceGatheringStateChange = new Event<[IceGathererState]>();
  readonly iceConnectionStateChange = new Event<[RTCIceConnectionState]>();
  readonly onIceCandidate = new Event<[IceCandidate | undefined]>();
  readonly connectionStateChange = new Event<[ConnectionState]>();

  private config: PeerConfig;
  private lastLocalCredentials?: { usernameFragment: string; password: string };
  private transceiverManager: TransceiverManager;
  private sctpManager: SctpTransportManager;
  /**
   * Every transport `createTransport` made that has not finished stopping
   * (`onStopped`). `close` stops all of them, so a transport no m-line
   * references any more (e.g. a max-compat transport a BUNDLE answer
   * replaced) never outlives the peer connection, and a transport whose DTLS
   * closed by alert keeps its ICE owned until stopped. Renegotiation does not
   * grow the set. Never used for the live-transport getters.
   */
  private readonly ownedTransports = new Set<RTCDtlsTransport>();

  constructor({
    config,
    transceiverManager,
    sctpManager,
  }: {
    config: PeerConfig;
    transceiverManager: TransceiverManager;
    sctpManager: SctpTransportManager;
  }) {
    this.config = config;
    this.transceiverManager = transceiverManager;
    this.sctpManager = sctpManager;

    if (this.config.dtls) {
      const { keys } = this.config.dtls;

      if (this.config.certificates[0]) {
        this.certificate = this.config.certificates[0];
      } else if (keys) {
        this.setupCertificate(keys);
      }
    }
  }

  /**live な m-line (停止確定していない transceiver / SCTP) が使う transport */
  get dtlsTransports() {
    return uniqueTransports([
      ...this.transceiverManager
        .getTransceivers()
        .filter((transceiver) => !transceiver.stopped)
        .map((transceiver) => transceiver.dtlsTransport),
      this.sctpManager.sctpTransport?.dtlsTransport,
    ]);
  }

  /**停止済み transceiver の transport も含めた全 transport */
  private get allDtlsTransports() {
    return uniqueTransports([
      ...this.transceiverManager.getTransceivers().map((t) => t?.dtlsTransport),
      this.sctpManager.sctpTransport?.dtlsTransport,
    ]);
  }

  get iceTransports() {
    return this.dtlsTransports.map((d) => d.iceTransport);
  }

  setupCertificate(keys: DtlsKeys) {
    this.certificate = new RTCCertificate(
      keys.keyPem,
      keys.certPem,
      keys.signatureHash,
    );
  }

  /**
   * Resolve STUN/TURN options from the current PeerConfig: every STUN URL and
   * every TURN URL of every RTCIceServer, in order. Each TURN URL keeps the
   * credential of its own RTCIceServer and its own transport (the URL's,
   * else turnTransport, else forceTurnTCP). A TURN URL without username /
   * credential cannot allocate and is left out (logged); W3C's
   * InvalidAccessError for it is not raised, for compatibility.
   *
   * Always returns every server-related field (the deprecated singular ones
   * as undefined) so Connection.setIceServers fully replaces residual TURN
   * servers and credentials.
   */
  private resolveIceServerOptions() {
    const { stunServers, turnServers } = parseIceServers(
      this.config.iceServers,
    );
    return {
      stunServers,
      turnServers: turnServers.flatMap(
        ({ address, username, password, transport }) => {
          if (!username || !password) {
            log("TURN server without username / credential ignored", address);
            return [];
          }
          return [
            {
              address,
              username,
              password,
              transport: resolveTurnTransport({
                parsedTurnTransport: transport,
                configuredTurnTransport: this.config.turnTransport,
                forceTurnTCP: this.config.forceTurnTCP,
              }),
            },
          ];
        },
      ),
      stunServer: undefined,
      turnServer: undefined,
      turnUsername: undefined,
      turnPassword: undefined,
      turnTransport: undefined,
    };
  }

  /**
   * The STUN/TURN settings the next gathering phase uses, resolved from the
   * current config (what `updateIceServers` hands to each transport).
   */
  iceServerSettings() {
    return {
      ...this.resolveIceServerOptions(),
      forceTurn: this.config.iceTransportPolicy === "relay",
      useTcp: this.config.iceUseTcp,
      turnTlsOptions: this.config.turnTlsOptions,
      turnUdpFamily: this.config.turnUdpFamily,
    };
  }

  /** Whether a live transport started gathering (its servers are in use). */
  get gatheringStarted() {
    return this.iceTransports.some(
      (iceTransport) => iceTransport.gatheringState !== "new",
    );
  }

  /**
   * Re-apply ICE servers from the current config.
   *
   * JSEP (RFC 9429 §4.1.18): server changes affect the next gathering phase.
   * A transport that has not gathered yet (`gatheringState === "new"`) takes
   * them now (e.g. TURN learned from a WHIP Link header before
   * setLocalDescription gathers). A transport that already gathered keeps its
   * live Connection untouched and takes them at its next ICE restart, which
   * also replaces a TURN allocation made with the old settings.
   */
  updateIceServers() {
    const options = this.iceServerSettings();
    for (const iceTransport of this.iceTransports) {
      if (iceTransport.gatheringState === "new") {
        iceTransport.setIceServers(options);
      } else {
        iceTransport.deferIceServers(options);
      }
    }
  }

  createTransport(option: boolean | { inheritCredentials?: boolean } = true) {
    const inheritCredentials =
      typeof option === "boolean"
        ? !option
        : option.inheritCredentials !== false;
    const independentIceCredentials = !inheritCredentials;
    const existing = inheritCredentials
      ? this.iceTransports.find((transport) => transport.state !== "closed")
      : undefined;

    const iceGatherer = new RTCIceGatherer({
      ...this.resolveIceServerOptions(),
      iceLite: this.config.iceLite,
      useDefaultStunServer: this.config.iceUseDefaultStunServer,
      forceTurn: this.config.iceTransportPolicy === "relay",
      portRange: this.config.icePortRange,
      interfaceAddresses: this.config.iceInterfaceAddresses,
      additionalHostAddresses: this.config.iceAdditionalHostAddresses,
      filterStunResponse: this.config.iceFilterStunResponse,
      filterCandidatePair: this.config.iceFilterCandidatePair,
      localPasswordPrefix: this.config.icePasswordPrefix,
      useIpv4: this.config.iceUseIpv4,
      useIpv6: this.config.iceUseIpv6,
      useTcp: this.config.iceUseTcp,
      tcpPassive: this.config.iceTcpPassive,
      stunGatherTimeout: this.config.iceStunGatherTimeout,
      turnConnectTimeout: this.config.iceTurnConnectTimeout,
      turnTlsOptions: this.config.turnTlsOptions,
      turnUdpFamily: this.config.turnUdpFamily,
      useLinkLocalAddress: this.config.iceUseLinkLocalAddress,
    });

    // ICE credentials change only on an ICE restart (JSEP 5.2.1). A transport
    // created after rollback discarded every live transport keeps the last
    // credentials, so a previously created description stays applicable.
    const inherited = existing
      ? {
          usernameFragment: existing.connection.localUsername,
          password: existing.connection.localPassword,
        }
      : !independentIceCredentials
        ? this.lastLocalCredentials
        : undefined;
    if (inherited) {
      iceGatherer.connection.localUsername = inherited.usernameFragment;
      iceGatherer.connection.localPassword = inherited.password;
    }
    if (!independentIceCredentials) {
      this.lastLocalCredentials = {
        usernameFragment: iceGatherer.connection.localUsername,
        password: iceGatherer.connection.localPassword,
      };
    }

    iceGatherer.onGatheringStateChange.subscribe(() => {
      this.updateIceGatheringState();
    });
    this.updateIceGatheringState();

    const iceTransport = new RTCIceTransport(iceGatherer);
    iceTransport.onStateChange.subscribe(() => {
      this.updateIceConnectionState();
    });

    const dtlsTransport = new RTCDtlsTransport(
      this.config,
      iceTransport,
      this.certificate,
      srtpProfiles,
    );
    this.ownedTransports.add(dtlsTransport);
    dtlsTransport.onStopped.once(() => {
      this.ownedTransports.delete(dtlsTransport);
    });

    return dtlsTransport;
  }

  /**
   * sdpMid / sdpMLineIndex は ICE transport を所有する受け入れ済み m-line
   * (BUNDLE なら tag) を呼び出し側で解決して渡す。
   */
  handleNewIceCandidate({
    candidate,
    sdpMid,
    sdpMLineIndex,
  }: {
    candidate: IceCandidate;
    sdpMid?: string;
    sdpMLineIndex?: number;
  }) {
    candidate.sdpMid = sdpMid;
    candidate.sdpMLineIndex = sdpMLineIndex;

    if (
      candidate.foundation &&
      !candidate.foundation.startsWith("candidate:")
    ) {
      candidate.foundation = "candidate:" + candidate.foundation;
    }

    this.onIceCandidate.execute(candidate);

    return candidate;
  }

  async addIceCandidate(
    sdp: SessionDescription,
    candidateMessage: RTCIceCandidate | RTCIceCandidateInit | null,
    applyToTransport = true,
  ) {
    const candidateText = candidateMessage?.candidate;
    const sdpMid = candidateMessage?.sdpMid;
    const sdpMLineIndex = candidateMessage?.sdpMLineIndex;
    const usernameFragment = candidateMessage?.usernameFragment;
    const isEndOfCandidates =
      candidateMessage == null || candidateText == null || candidateText === "";
    const mediaIndices = this.resolveCandidateMediaIndices({
      sdp,
      isEndOfCandidates,
      sdpMid,
      sdpMLineIndex,
      usernameFragment,
    });

    if (isEndOfCandidates) {
      const unfinished = mediaIndices.filter(
        (index) => !sdp.media[index]?.iceCandidatesComplete,
      );
      if (unfinished.length === 0) return;
      const candidateTarget = unfinished
        .map((index) => this.getTransportByMLineIndex(sdp, index))
        .filter(
          (iceTransport): iceTransport is RTCIceTransport => !!iceTransport,
        )
        .reduce((acc: RTCIceTransport[], transport) => {
          if (!acc.find(({ id }) => id === transport.id)) {
            acc.push(transport);
          }
          return acc;
        }, []);

      if (applyToTransport) {
        for (const iceTransport of candidateTarget) {
          iceTransport.deliverRemoteCandidate(undefined);
        }
      }
      return {
        kind: "end-of-candidates" as const,
        mediaIndices: unfinished,
      };
    }

    const candidate = IceCandidate.fromJSON(candidateMessage);
    if (!candidate) {
      throw createWebRtcDomException(
        "OperationError",
        "Failed to parse ICE candidate",
      );
    }

    const targetMediaIndex = mediaIndices[0];
    const targetMedia = sdp.media[targetMediaIndex];
    if (!targetMedia) {
      throw createWebRtcDomException(
        "OperationError",
        "ICE media section not found",
      );
    }
    candidate.sdpMid = targetMedia.rtp.muxId ?? undefined;
    candidate.sdpMLineIndex = targetMediaIndex;

    if (
      targetMedia.iceCandidates.some(
        (existing) =>
          existing.toJSON().candidate === candidate.toJSON().candidate,
      )
    ) {
      return;
    }
    // RFC 8838: the generation of this m-line already ended. The candidate is
    // ignored, so it reaches neither the SDP nor any (live, pending-only or
    // provisional) checklist of that generation.
    if (targetMedia.iceCandidatesComplete) {
      return;
    }

    const iceTransport = this.getTransportByMLineIndex(sdp, targetMediaIndex);

    if (!iceTransport && applyToTransport) {
      if (this.isRejectedMedia(targetMedia)) {
        return {
          kind: "candidate" as const,
          candidate,
          mediaIndices: [targetMediaIndex],
        };
      }
      throw createWebRtcDomException(
        "OperationError",
        "ICE transport not found for candidate",
      );
    }

    if (applyToTransport) iceTransport?.deliverRemoteCandidate(candidate);
    return {
      kind: "candidate" as const,
      candidate,
      mediaIndices: [targetMediaIndex],
    };
  }

  private resolveCandidateMediaIndices({
    sdp,
    isEndOfCandidates,
    sdpMid,
    sdpMLineIndex,
    usernameFragment,
  }: {
    sdp: SessionDescription;
    isEndOfCandidates: boolean;
    sdpMid?: string | null;
    sdpMLineIndex?: number | null;
    usernameFragment?: string | null;
  }) {
    let mediaIndices: number[];

    if (typeof sdpMid === "string") {
      const mediaIndex = sdp.media.findIndex(
        (media) => media.rtp.muxId === sdpMid,
      );
      if (mediaIndex < 0) {
        throw createWebRtcDomException(
          "OperationError",
          "Media section for sdpMid was not found",
        );
      }
      mediaIndices = [mediaIndex];
    } else if (typeof sdpMLineIndex === "number") {
      if (sdpMLineIndex < 0 || sdpMLineIndex >= sdp.media.length) {
        throw createWebRtcDomException(
          "OperationError",
          "Media section for sdpMLineIndex was not found",
        );
      }
      mediaIndices = [sdpMLineIndex];
    } else if (isEndOfCandidates) {
      mediaIndices = sdp.media.map((_, index) => index);
    } else {
      throw createWebRtcTypeError(
        "sdpMid or sdpMLineIndex must be provided with a candidate",
      );
    }

    if (typeof usernameFragment === "string") {
      const matchingIndices = mediaIndices.filter(
        (index) =>
          sdp.media[index]?.iceParams?.usernameFragment === usernameFragment,
      );
      if (matchingIndices.length === 0) {
        throw createWebRtcDomException(
          "OperationError",
          "No media section matched the ICE usernameFragment",
        );
      }
      mediaIndices = matchingIndices;
    }

    return mediaIndices;
  }

  private isRejectedMedia(media: MediaDescription) {
    if (media.port === 0) {
      return true;
    }
    if (!["audio", "video"].includes(media.kind)) {
      return false;
    }
    const transceiver = this.transceiverManager
      .getTransceivers()
      .find((t) => t.mid != undefined && t.mid === media.rtp.muxId);
    return (
      !transceiver ||
      transceiver.stopped ||
      transceiver.stopping ||
      transceiver.pendingRejection
    );
  }

  private getTransportByMid(mid?: string) {
    if (!mid) {
      return;
    }
    let iceTransport: RTCIceTransport | undefined;

    const transceiver = this.transceiverManager
      .getTransceivers()
      .find((t) => t.mid === mid);
    if (transceiver) {
      iceTransport = transceiver.dtlsTransport?.iceTransport;
    } else if (!iceTransport && this.sctpManager.sctpTransport?.mid === mid) {
      iceTransport = this.sctpManager.sctpTransport.dtlsTransport.iceTransport;
    }

    if (iceTransport?.state === "closed") {
      return;
    }
    return iceTransport;
  }

  private getTransportByMLineIndex(sdp: SessionDescription, index: number) {
    const media = sdp.media[index];
    if (!media) {
      return;
    }
    const transport = this.getTransportByMid(media.rtp.muxId!);

    return transport;
  }

  restartIce() {
    for (const transport of this.iceTransports) {
      transport.restart();
    }
    const [first] = this.iceTransports;
    if (first) this.lastLocalCredentials = first.localParameters;
    // restart() resets each gatherer to "new"; refresh the aggregate cache
    // even if a gatherer failed to emit onGatheringStateChange.
    this.updateIceGatheringState();
  }

  /** Stage restart credentials on `targets` (all transports by default). */
  stageIceRestart(
    targets?: ReadonlySet<RTCIceTransport>,
    {
      answering,
      replacing,
    }: { answering?: object; replacing?: ReadonlySet<string> } = {},
  ) {
    for (const transport of this.iceTransports) {
      // A transport without a generation yet (never gathered, e.g. created
      // for a new m-line beside the restart) starts with fresh credentials
      // anyway; staging would advertise its empty candidate list as complete.
      const hasGeneration =
        transport.gatheringState !== "new" && !!transport.getRemoteParameters();
      if ((!targets || targets.has(transport)) && hasGeneration) {
        transport.stageLocalRestart({ answering, replacing });
      } else {
        transport.rollbackLocalRestart();
      }
    }
  }

  rollbackStagedIceRestart() {
    for (const transport of this.iceTransports) {
      transport.rollbackLocalRestart();
    }
  }

  /** The staged restart credentials now belong to an applied description. */
  markStagedIceRestartApplied() {
    for (const transport of this.iceTransports) {
      transport.markLocalRestartApplied();
    }
  }

  /** Discard restart credentials staged only by an unapplied createOffer. */
  discardUnappliedIceRestart() {
    for (const transport of this.iceTransports) {
      transport.discardUnappliedLocalRestart();
    }
  }

  emitStagedIceCandidates() {
    for (const transport of this.iceTransports) {
      transport.emitStagedCandidates();
    }
  }

  emitCommittedIceCandidates() {
    for (const transport of this.iceTransports) {
      transport.emitCommittedCandidates();
    }
  }

  /**
   * Called unconditionally whenever a remote answer is applied. Whether ICE
   * actually restarts depends on each transport's own state: only transports
   * that staged a local restart for the applied offer do anything; the rest
   * no-op inside `commitLocalRestartIfStaged`.
   */
  async commitIceRestartIfAnyStaged() {
    await Promise.all(
      this.iceTransports.map((transport) =>
        transport.commitLocalRestartIfStaged(),
      ),
    );
    const [first] = this.iceTransports;
    if (first) this.lastLocalCredentials = first.localParameters;
    this.updateIceGatheringState();
  }

  setLocalRole({
    type,
    role,
  }: {
    type: "offer" | "answer";
    /** answer で transport に設定する DTLS role。undefined なら現在の role を保つ */
    role: (
      transport: RTCDtlsTransport,
    ) => "auto" | "client" | "server" | undefined;
  }) {
    for (const dtlsTransport of this.dtlsTransports) {
      const iceTransport = dtlsTransport.iceTransport;
      if (iceTransport.connection.iceLite) {
        iceTransport.connection.iceControlling = false;
      } else if (iceTransport.connection.remoteIsLite) {
        // RFC 8445 S6.1.1
        iceTransport.connection.iceControlling = true;
      } else if (type === "offer") {
        iceTransport.connection.iceControlling = true;
      } else {
        iceTransport.connection.iceControlling = false;
      }

      // # set DTLS role for mediasoup
      if (type === "answer") {
        const transportRole = role(dtlsTransport);
        if (transportRole) {
          dtlsTransport.role = transportRole;
        }
      }
    }
  }

  // https://w3c.github.io/webrtc-pc/#dom-rtcicegatheringstate
  private updateIceGatheringState() {
    const all = this.iceTransports;

    function allMatch(...state: IceGathererState[]) {
      return (
        all.filter((check) => state.includes(check.gatheringState)).length ===
        all.length
      );
    }

    let newState: IceGathererState;

    if (all.length && allMatch("complete")) {
      newState = "complete";
    } else if (!all.length || allMatch("new", "complete")) {
      newState = "new";
    } else if (all.map((check) => check.gatheringState).includes("gathering")) {
      newState = "gathering";
    } else {
      newState = "new";
    }

    if (this.iceGatheringState === newState) {
      return;
    }

    this.iceGatheringState = newState;
    this.iceGatheringStateChange.execute(newState);
  }

  // https://w3c.github.io/webrtc-pc/#dom-rtciceconnectionstate
  updateIceConnectionState() {
    const all = this.iceTransports;
    let newState: RTCIceConnectionState;

    function allMatch(...state: RTCIceConnectionState[]) {
      return (
        all.filter((check) => state.includes(check.state)).length === all.length
      );
    }

    function anyMatch(...state: RTCIceConnectionState[]) {
      return all.some((check) => state.includes(check.state));
    }

    if (this.connectionState === "closed") {
      newState = "closed";
    } else if (anyMatch("failed")) {
      newState = "failed";
    } else if (anyMatch("disconnected")) {
      newState = "disconnected";
    } else if (allMatch("new", "closed")) {
      newState = "new";
    } else if (anyMatch("new", "checking")) {
      newState = "checking";
    } else if (allMatch("completed", "closed")) {
      newState = "completed";
    } else if (allMatch("connected", "completed", "closed")) {
      newState = "connected";
    } else {
      // unreachable?
      newState = "new";
    }

    if (this.iceConnectionState === newState) {
      return;
    }

    log("iceConnectionStateChange", newState);
    this.iceConnectionState = newState;
    this.iceConnectionStateChange.execute(newState);

    // Runtime ICE failure (e.g. RFC 7675 consent expiry) must surface on
    // PeerConnection.connectionState without treating it as an explicit close().
    if (newState === "failed" && this.connectionState !== "closed") {
      this.setConnectionState("failed");
    } else if (
      newState === "disconnected" &&
      this.connectionState === "connected"
    ) {
      this.setConnectionState("disconnected");
    }
  }

  async gatherCandidates() {
    // Partial BUNDLE topology can have an established owner and newly added transports.
    await Promise.allSettled(
      this.iceTransports
        .filter(
          (iceTransport) =>
            iceTransport.state !== "closed" &&
            iceTransport.gatheringState === "new",
        )
        .map((iceTransport) => iceTransport.gather()),
    );
  }

  setConnectionState(state: ConnectionState) {
    if (this.connectionState === state) {
      return;
    }
    log("connectionStateChange", state);
    this.connectionState = state;
    this.connectionStateChange.execute(state);
  }

  async getStats(timestamp?: number): Promise<RTCStats[]> {
    const stats: RTCStats[] = [];

    for (const dtlsTransport of this.dtlsTransports) {
      const transportStats = await dtlsTransport.getStats(timestamp);
      if (transportStats) {
        stats.push(...transportStats);
      }
    }

    return stats;
  }

  /**
   * Without `certificates` / `dtls.keys`, `certificateScope` decides the default:
   * - `"process"` (default): the certificate shared by the whole process.
   * - `"peerConnection"`: a certificate generated for this peer connection (like browsers),
   *   kept for its lifetime; every DTLS transport of this peer connection uses it.
   */
  async ensureCerts() {
    if (!this.certificate) {
      if (this.config.certificateScope === "peerConnection") {
        this.certificatePromise ??= RTCDtlsTransport.generateCertificate();
        try {
          this.certificate ??= await this.certificatePromise;
        } catch (error) {
          // let the next createOffer / createAnswer retry the generation
          this.certificatePromise = undefined;
          throw error;
        }
      } else {
        this.certificate = await RTCDtlsTransport.SetupCertificate();
      }
    }

    for (const dtlsTransport of this.dtlsTransports) {
      dtlsTransport.localCertificate = this.certificate;
    }
  }

  async close() {
    this.setConnectionState("closed");

    // Owned transports cover the ones no binding references any more.
    await Promise.allSettled(
      uniqueTransports([
        ...this.allDtlsTransports,
        ...this.ownedTransports,
      ]).map((t) => t.stop()),
    );
    this.ownedTransports.clear();

    this.iceGatheringStateChange.allUnsubscribe();
    this.iceConnectionStateChange.allUnsubscribe();
    this.onIceCandidate.allUnsubscribe();
    this.connectionStateChange.allUnsubscribe();
  }
}

function uniqueTransports(transports: (RTCDtlsTransport | undefined)[]) {
  return transports.reduce((acc: RTCDtlsTransport[], cur) => {
    if (cur && !acc.map((d) => d.id).includes(cur.id)) {
      acc.push(cur);
    }
    return acc;
  }, []);
}

const srtpProfiles = [
  SRTP_PROFILE.SRTP_AEAD_AES_128_GCM, // prefer
  SRTP_PROFILE.SRTP_AES128_CM_HMAC_SHA1_80,
];
